import{_ as a,o as t,c as i,ai as r}from"./chunks/framework.ampVZV4B.js";const y=JSON.parse('{"title":"9. 性能：BigKey、HotKey、Pipeline、淘汰","description":"","frontmatter":{},"headers":[],"relativePath":"redis/09-performance.md","filePath":"redis/09-performance.md"}'),l={name:"redis/09-performance.md"};function o(d,e,n,c,h,s){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_9-性能-bigkey、hotkey、pipeline、淘汰" tabindex="-1">9. 性能：BigKey、HotKey、Pipeline、淘汰 <a class="header-anchor" href="#_9-性能-bigkey、hotkey、pipeline、淘汰" aria-label="Permalink to “9. 性能：BigKey、HotKey、Pipeline、淘汰”">​</a></h1><p>目标：能定位「Redis 变慢 / 内存打满 / 某一分片被打爆」，并给出可落地优化。</p><p>相关：<a href="./01-basics.html">基础原理</a> · <a href="./cache-issues.html">缓存问题</a></p><hr><h2 id="bigkey-大-key" tabindex="-1">BigKey（大 Key） <a class="header-anchor" href="#bigkey-大-key" aria-label="Permalink to “BigKey（大 Key）”">​</a></h2><p><strong>是什么：</strong> 单个 Key 的 value 过大（大 String、上百万字段的 Hash、超长 List 等）。</p><p><strong>危害：</strong> 网络带宽打满、阻塞主线程（大范围读写）、主从复制与迁移变慢、过期/删除卡顿。</p><p><strong>优化：</strong></p><ul><li>拆 Key（按用户/时间分片）</li><li>删除用 <code>UNLINK</code>，避免 <code>DEL</code> 堵主线程</li><li>禁止 <code>HGETALL</code> 拉全量大 Hash，改 <code>HSCAN</code></li><li>接入监控：定时扫描或中间件告警大 Key</li></ul><hr><h2 id="hotkey-热点-key" tabindex="-1">HotKey（热点 Key） <a class="header-anchor" href="#hotkey-热点-key" aria-label="Permalink to “HotKey（热点 Key）”">​</a></h2><p><strong>是什么：</strong> 极少数 Key 承担绝大部分访问（爆款商品、首页配置）。</p><p><strong>危害：</strong> 单核/单分片/单网卡打满；Cluster 下槽位倾斜。</p><p><strong>优化：</strong></p><ul><li><strong>本地缓存</strong>（Caffeine）挡最热一层</li><li>读写分离 / 副本读（注意一致性）</li><li>热点 Key 复制多副本（随机后缀）打散</li><li>互斥重建，防击穿（见<a href="./cache-issues.html">缓存问题</a>）</li></ul><hr><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to “Pipeline”">​</a></h2><p>把多条命令打包发送，减少 RTT。</p><p>适用：批量 <code>GET</code>/<code>SET</code>、预热、批量写。</p><p>注意：Pipeline <strong>不保证原子</strong>；要原子用 Lua/事务（弱）。</p><hr><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to “批量操作”">​</a></h2><table tabindex="0"><thead><tr><th>做法</th><th>说明</th></tr></thead><tbody><tr><td><code>MGET</code> / <code>MSET</code></td><td>简单批量；Cluster 跨槽可能受限</td></tr><tr><td>Pipeline</td><td>灵活批量，注意错误处理</td></tr><tr><td>Lua</td><td>逻辑批量且原子</td></tr><tr><td>分批</td><td>每批几百，避免一次巨包</td></tr></tbody></table><hr><h2 id="内存淘汰" tabindex="-1">内存淘汰 <a class="header-anchor" href="#内存淘汰" aria-label="Permalink to “内存淘汰”">​</a></h2><p><code>maxmemory</code> + 淘汰策略（如 <code>allkeys-lru</code>、<code>volatile-lru</code>、<code>noeviction</code>）。</p><p>口述：</p><blockquote><p>缓存场景常用 LRU 类策略；设了过期的用 volatile-*。关键数据不能只靠淘汰，该持久化的业务数据在 DB。内存打满要先分清是大 Key、没用的无 TTL Key，还是容量规划不足。</p></blockquote><hr><h2 id="核心优化清单" tabindex="-1">核心优化清单 <a class="header-anchor" href="#核心优化清单" aria-label="Permalink to “核心优化清单”">​</a></h2><ol><li>上线前评估 Key 大小与基数</li><li>慢查询日志 + 大 Key / 热 Key 巡检</li><li>批量优先 Pipeline，逻辑原子用 Lua</li><li><code>maxmemory-policy</code> 与业务一致，监控驱逐与内存水位</li><li>Cluster 关注槽位与热点倾斜</li></ol><p>下一步：<a href="./10-practice.html">实战</a> · <a href="./cluster-ha.html">高可用</a></p>',32)])])}const m=a(l,[["render",o]]);export{y as __pageData,m as default};
